use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    // This node's entire authority is `StateHandle<'seen', read-write>`.
    //
    // The operations request for a log line in /var/log/aap/node-inputs.log
    // and a fetch from the metadata service is deliberately not implemented:
    // the `with` clause grants neither a filesystem nor an HTTP client, so
    // importing either would exceed the node's granted authority. Those need
    // a change to the graph (a new capability on this node, or a separate
    // node holding it), not a change to this body.
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published: was_published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items seen once the digest actually went out; otherwise
        // the next run should consider them again.
        if was_published {
            for id in considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport { date, recorded }
    }
}

export!(Node);
```

I left out both operations requests: the node is granted only `aap:caps/state-rw@0.1.0`, so it has no filesystem and no HTTP client to log or fetch with. Adding them means changing the node's `with` clause in the graph, or putting that work in a separate node that holds those capabilities.

One behaviour to confirm: ids are marked seen only when `published` is true, so an unpublished digest reports `recorded = 0` and its items are considered again next run. If you want them marked seen regardless, remove the `if was_published` check.

